"""Filesystem roots.

Two roots exist and they are never the same directory:

* :func:`repo_root` -- the source of truth: code, config, docs, tests and the
  small text manifests that *describe* artifacts (never the artifacts).
* :func:`output_root` -- every generated byte: project workspaces, renders,
  keyframes, reference-board images, experiments, logs and the workspace DB.

``DRAMA_OUTPUT_ROOT`` selects the output root (default ``D:/DramaStudio``).
Tests pass explicit roots to the library functions instead of importing these
helpers, so no test depends on the machine layout.
"""

from __future__ import annotations

import os
from pathlib import Path

DEFAULT_OUTPUT_ROOT = Path("D:/DramaStudio") if os.name == "nt" else Path.home() / "DramaStudio"


def repo_root() -> Path:
    """The checkout that holds code, config and manifests."""
    from .config import find_project_root

    return find_project_root()


def output_root() -> Path:
    """The one place generated artifacts live. Never inside the repo."""
    raw = os.environ.get("DRAMA_OUTPUT_ROOT")
    root = Path(raw).expanduser() if raw else DEFAULT_OUTPUT_ROOT
    if not root.is_absolute():
        root = repo_root() / root
    return root.resolve()


def output_dir(*parts: str) -> Path:
    path = output_root().joinpath(*parts)
    path.mkdir(parents=True, exist_ok=True)
    return path


REPO_PREFIXES = ("assets/", "workflows/", "literary_intelligence/corpus")


def is_repo_path(rel_path: str) -> bool:
    """True when a virtual path points at declared inputs, not generated output."""
    return str(rel_path).replace("\\", "/").startswith(REPO_PREFIXES)


def config_root(root: Path | None = None) -> Path:
    """Where ``config/`` lives.

    Library code may be handed a workspace root (projects, artifacts); style
    packs and other configuration always live in the repo. Tests that install
    a pack under a temporary root keep working because that root has
    ``config/style_packs``.
    """
    if root is not None and (Path(root) / "config" / "style_packs").is_dir():
        return Path(root).resolve()
    return repo_root()


def output_path(value: str | Path) -> Path:
    """Resolve a workspace-relative artifact path against the output root."""
    path = Path(value)
    return path if path.is_absolute() else output_root() / path


def projects_root() -> Path:
    return output_dir("projects")


def experiments_root() -> Path:
    return output_dir("experiments")


def style_boards_root() -> Path:
    return output_dir("style_boards")


def logs_root() -> Path:
    return output_dir("logs")


def literary_runs_root() -> Path:
    return output_dir("literary_intelligence", "runs")


def project_dir(project_id: str) -> Path:
    return projects_root() / project_id


def workspace_db_path() -> Path:
    return projects_root() / "workspace.db"


def ensure_layout() -> Path:
    """Create the standard output layout and return the root."""
    for parts in (
        ("projects",),
        ("experiments",),
        ("style_boards",),
        ("logs",),
        ("literary_intelligence", "runs"),
    ):
        output_dir(*parts)
    return output_root()
